<template><section class="manager"><header><div><h3><PosIcon name="clipboard-list" size="20" /> Prescription Intake</h3><p>Medication and prescription data are loaded from the pharmacy service.</p></div></header><p v-if="loading" class="state">Loading prescription data…</p><p v-else-if="error" class="state error">{{ error }}</p><p v-else-if="!prescriptions.length" class="state">No prescriptions are waiting for processing.</p><div v-else class="cards"><article v-for="rx in prescriptions" :key="rx.id"><div><strong>{{ rx.rx_number }}</strong><span>{{ rx.patient_name }} · {{ rx.doctor_name }}</span><small>{{ rx.status }}</small></div><strong>KES {{ money(rx.total_minor) }}</strong><button @click="dispense(rx)">Dispense</button></article></div></section></template>
<script setup>
import { onMounted,ref } from 'vue'; import { PosIcon } from '@pos/ui'; import { useApi } from '../../../../apps/pos/src/composables/useApi.js'
const emit=defineEmits(['add-item','notification']); const api=useApi(); const prescriptions=ref([]); const loading=ref(true); const error=ref(''); onMounted(async()=>{try{const data=await api.get('/api/v1/pharmacy/prescriptions');prescriptions.value=data.items??[]}catch{error.value='Prescriptions could not be loaded. Please contact your administrator.'}finally{loading.value=false}}); function money(v){return(Number(v||0)/100).toLocaleString()} function dispense(rx){emit('notification',{message:`Prescription ${rx.rx_number} is ready for dispensing`,type:'info'})}
</script>
<style scoped>.manager{display:flex;flex-direction:column;gap:16px}header h3{display:flex;align-items:center;gap:8px;margin:0;color:#1e293b}header p{margin:4px 0;color:#64748b;font-size:12px}.state{padding:24px;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;text-align:center;font-size:12px}.state.error{border-color:#fecaca;color:#b91c1c}.cards{display:flex;flex-direction:column;gap:8px}.cards article{display:flex;align-items:center;gap:12px;padding:12px;border:1px solid #e2e8f0;border-radius:8px}.cards article div{flex:1}.cards span,.cards small{display:block;color:#64748b;font-size:11px}.cards button{padding:7px 10px;border:0;border-radius:6px;background:#0284c7;color:#fff;font-size:11px;cursor:pointer}</style>
